// Define all bridges to monitor
const bridges = [
  { name: 'github-bridge', port: 7811, priority: 'critical' },
  { name: 'supabase-bridge', port: 7812, priority: 'critical' },
  { name: 'firebase-bridge', port: 7813, priority: 'medium' },
  { name: 'postgres-bridge', port: 7814, priority: 'critical' },
  { name: 'slack-bridge', port: 7815, priority: 'high' },
  { name: 'openai-bridge', port: 7816, priority: 'medium' },
  { name: 'anthropic-bridge', port: 7817, priority: 'medium' },
  { name: 'google-bridge', port: 7818, priority: 'medium' },
  { name: 'filesystem-bridge', port: 7819, priority: 'high' }
];

return bridges.map(b => ({
  json: {
    ...b,
    healthUrl: `http://localhost:${b.port}/health`,
    timestamp: new Date().toISOString()
  }
}));

const items = $input.all();
const results = [];
const failures = [];

for (const item of items) {
  const bridge = item.json;
  const response = item.json;

  const result = {
    name: bridge.name || 'unknown',
    port: bridge.port,
    priority: bridge.priority,
    timestamp: new Date().toISOString(),
    status: 'unknown',
    latency_ms: null,
    error: null
  };

  // Check if request succeeded
  if (response.status === 'healthy') {
    result.status = 'healthy';
    result.details = response;
  } else if (response.error || response.statusCode >= 400) {
    result.status = 'unhealthy';
    result.error = response.error || response.message || `HTTP ${response.statusCode}`;
    failures.push(result);
  } else {
    result.status = 'healthy';
    result.details = response;
  }

  results.push({ json: result });
}

// Add summary
const healthy = results.filter(r => r.json.status === 'healthy').length;
const unhealthy = results.filter(r => r.json.status === 'unhealthy').length;

const summary = {
  json: {
    type: 'summary',
    timestamp: new Date().toISOString(),
    total: results.length,
    healthy,
    unhealthy,
    failures: failures.map(f => f.name),
    alert_required: failures.some(f => f.priority === 'critical')
  }
};

return [...results, summary];

